async function e(){let e=document.querySelector(`#pong-status`);if(!(`DecompressionStream`in window))e.textContent=`このブラウザーはゲームの圧縮データ展開に対応していません。新しいブラウザーで開いてください。`;else try{let e=new URL(`./main.js.gz`,import.meta.url),t=await fetch(e);if(!t.ok)throw Error(`ゲーム本体を取得できませんでした (${t.status})`);let n=t.body.pipeThrough(new DecompressionStream(`gzip`)),r=await new Response(n).blob(),i=URL.createObjectURL(new Blob([r],{type:`text/javascript`}));try{await import(i)}finally{URL.revokeObjectURL(i)}}catch(t){e.textContent=`ゲームを読み込めませんでした。ページを再読み込みしてください。`,console.error(`卓球ゲームの読み込みに失敗しました。`,t)}}e();